<?php $pageTitle='Collections';require 'includes/header.php';require 'includes/navbar.php';$cats=db()->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.status="active" GROUP BY c.id ORDER BY c.name')->fetchAll(); ?><main class="container my-5"><h1 class="section-title">Oversized collections</h1><p class="text-muted">Every OVERSO collection contains oversized T-shirts only.</p><div class="row g-3"><?php foreach($cats as $c): ?><div class="col-6 col-md-4"><a class="collection" href="<?=base('products.php?category='.$c['id'])?>"><span><?=e($c['name'])?><small class="d-block fs-6 fw-normal mt-2"><?=$c['product_count']?> styles</small></span></a></div><?php endforeach ?></div></main><?php require 'includes/footer.php'; ?>
